insert into public.library_items (category, title, content, tags) values
('marketing_case','나이키 — Just Do It', '{"company":"Nike","campaign":"Just Do It","industry":"스포츠용품","year":"1988~","background":"1980년대 나이키는 리복에 밀려 경쟁에서 뒤처지고 있었고, 기능이 아니라 태도를 파는 브랜드로 전환할 메시지가 필요했다.","strategy":"특정 제품을 설명하지 않고 도전과 실행이라는 감정적 메시지에 집중하고, 무명 선수부터 스타 선수까지 다양한 인물을 통해 슬로건을 반복 노출했다.","result":"슬로건 도입 후 나이키의 미국 스포츠화 시장 점유율이 크게 상승했고, Just Do It은 30년 넘게 브랜드 정체성의 핵심으로 유지되고 있다.","lesson":"제품 스펙보다 고객이 자신을 어떻게 느끼고 싶어하는지에 메시지를 맞추면, 촬영 결과물도 스펙 나열이 아니라 이 병원을 선택하면 어떤 기분일지를 전달하는 방향으로 설계할 수 있다."}', '{브랜딩,슬로건}'),
('marketing_case','애플 — Think Different', '{"company":"Apple","campaign":"Think Different","industry":"IT/전자제품","year":"1997","background":"1997년 잡스가 복귀했을 때 애플은 파산 위기였고, 기술 스펙 경쟁에서는 마이크로소프트에 밀리고 있었다.","strategy":"자사 제품을 전혀 보여주지 않고 아인슈타인·간디 등 세상을 바꾼 인물들의 흑백 사진과 함께 브랜드가 지향하는 가치관만 전달했다.","result":"캠페인 이후 애플은 적자에서 벗어나기 시작했고, 이후 아이맥·아이팟 등 후속 제품 성공의 토대가 되는 브랜드 정체성을 재구축했다.","lesson":"위기일수록 제품을 파는 대신 어떤 가치를 믿는 브랜드인지부터 명확히 하면, 이후 어떤 서비스를 붙여도 일관된 메시지로 확장할 수 있다."}', '{브랜딩,정체성}'),
('marketing_case','에어비앤비 — Belong Anywhere', '{"company":"Airbnb","campaign":"Belong Anywhere","industry":"공유숙박","year":"2014~","background":"초기 에어비앤비는 낯선 사람 집에서 자는 것에 대한 신뢰 문제가 가장 큰 장벽이었다.","strategy":"숙박이 아니라 소속감을 판다는 포지셔닝으로 전환하고, 실제 호스트·게스트의 사용자생성콘텐츠(UGC)와 지역 스토리를 마케팅의 중심에 두었다.","result":"신뢰 기반 UGC 전략은 별도의 대형 광고 없이도 호스트·게스트 커뮤니티를 자발적으로 확장시키는 원동력이 됐다.","lesson":"신뢰가 핵심 장벽인 업종(병원도 마찬가지)에서는 브랜드가 스스로 말하는 것보다 실제 이용자의 후기·사진이 훨씬 강력한 마케팅 자산이 된다."}', '{포지셔닝,UGC}'),
('marketing_case','도브 — Real Beauty', '{"company":"Dove","campaign":"Campaign for Real Beauty","industry":"뷰티/생활용품","year":"2004~","background":"뷰티 업계는 오랫동안 비현실적인 미의 기준을 광고에 사용해왔고, 도브는 여기에 반기를 드는 포지셔닝으로 차별화를 시도했다.","strategy":"전문 모델 대신 일반 여성을 광고 모델로 기용하고, 사회적 논의를 촉발하는 메시지를 의도적으로 던졌다.","result":"논쟁적인 소재였음에도 브랜드 호감도와 언론 노출이 크게 늘었고, 이후 여러 뷰티 브랜드가 유사한 있는 그대로 메시지를 따라가는 계기가 됐다.","lesson":"업계의 당연한 관행에 반대되는 메시지를 던지면 리스크는 있지만, 그만큼 화제성과 브랜드 각인 효과는 커진다."}', '{사회적마케팅,논쟁마케팅}'),
('marketing_case','올드스파이스 — The Man Your Man Could Smell Like', '{"company":"Old Spice","campaign":"The Man Your Man Could Smell Like","industry":"생활용품","year":"2010","background":"올드스파이스는 아버지 세대의 브랜드로 인식돼 젊은 소비자층에게서 멀어지고 있었다.","strategy":"유머러스한 톤의 짧은 광고 영상을 만들고, 소셜미디어 상의 실제 댓글에 배우가 직접 즉석에서 답하는 영상을 대량 제작해 2차 화제를 만들었다.","result":"캠페인 기간 동안 매출과 온라인 화제성이 동시에 급증했고, 노후 브랜드 이미지를 반전시킨 대표 사례로 지금도 마케팅 교육에서 인용된다.","lesson":"예산을 한 편의 완벽한 광고에 쓰기보다, 실시간 반응형 콘텐츠를 빠르게 대량 생산하는 방식이 화제성 측면에서 더 효율적일 수 있다."}', '{바이럴,리브랜딩}'),
('marketing_case','코카콜라 — Share a Coke', '{"company":"Coca-Cola","campaign":"Share a Coke","industry":"음료","year":"2011~","background":"탄산음료 소비가 건강 트렌드로 정체되던 시기, 코카콜라는 개인적 연결을 만들 방법이 필요했다.","strategy":"제품 라벨에 흔한 이름을 인쇄해 개인화하고, 소비자가 직접 사진을 찍어 공유하도록 유도했다.","result":"젊은 소비자층의 참여와 SNS 언급량이 크게 늘었고, 이후 여러 국가에서 현지 이름 버전으로 확장 운영됐다.","lesson":"결과물에 고객의 이름이나 개인 정보를 살짝 넣는 것만으로도 자발적 공유 욕구를 만들 수 있다 — 예: 리뷰 콘텐츠에 원장님·환자 이니셜을 넣는 식."}', '{개인화,SNS확산}'),
('marketing_case','레드불 — 콘텐츠 마케팅', '{"company":"Red Bull","campaign":"Stratos / 미디어하우스 전략","industry":"음료","year":"2012~","background":"에너지드링크 시장에서 제품 자체의 차별점을 광고로 설명하기 어려웠던 레드불은 다른 접근이 필요했다.","strategy":"스스로를 에너지드링크 회사가 아니라 익스트림스포츠 미디어 회사로 재정의하고, 성층권 낙하 같은 자체 이벤트·콘텐츠를 제작해 배포했다.","result":"레드불 스트라토스 등 자체 제작 콘텐츠는 전 세계적으로 큰 화제를 모았고, 제품 판매보다 브랜드 콘텐츠 자체가 마케팅 자산이 되는 모델을 증명했다.","lesson":"촬영 스튜디오도 고객 결과물을 납품하는 곳을 넘어 자체 콘텐츠(가이드, 트렌드 리포트 등)를 꾸준히 만들면 그 자체가 신뢰 자산이 된다."}', '{콘텐츠마케팅,브랜디드콘텐츠}'),
('marketing_case','스포티파이 — Wrapped', '{"company":"Spotify","campaign":"Spotify Wrapped","industry":"음악스트리밍","year":"2016~","background":"스트리밍 서비스는 대체재가 많아 매년 재계약 시점마다 이탈 위험이 있었고, 사용자와의 정서적 연결이 필요했다.","strategy":"개인별 청취 데이터를 연말에 시각화된 카드 형태로 제공해 소비자가 자발적으로 SNS에 공유하도록 설계했다.","result":"매년 공개 시즌마다 소셜미디어 상에서 자발적 확산이 반복되는, 별도 광고비 없이도 작동하는 연례 바이럴 자산으로 자리잡았다.","lesson":"고객이 이미 갖고 있는 데이터(촬영 이력, 방문 횟수 등)를 개인화된 형태로 되돌려주면 그 자체가 공유하고 싶은 콘텐츠가 될 수 있다."}', '{데이터마케팅,개인화}'),
('marketing_case','파타고니아 — Don''t Buy This Jacket', '{"company":"Patagonia","campaign":"Don''t Buy This Jacket","industry":"아웃도어","year":"2011","background":"아웃도어 브랜드 중에서도 파타고니아는 환경 가치를 핵심 정체성으로 삼고 있었고, 블랙프라이데이 과소비 문화에 반하는 메시지가 필요했다.","strategy":"블랙프라이데이에 이 재킷을 사지 말라는 역설적 광고를 게재해 과소비 대신 수선·재사용을 독려했다.","result":"역설적으로 판매량과 브랜드 신뢰도가 동시에 상승했고, 지속가능성을 핵심 가치로 내세우는 브랜드의 대표 사례로 지금도 인용된다.","lesson":"진짜 신념에 기반한 메시지는 단기적으로 판매를 줄이는 것처럼 보여도 장기적 신뢰를 더 크게 쌓을 수 있다."}', '{지속가능성,역설적마케팅}'),
('marketing_case','이케아 — 이케아 효과 활용', '{"company":"IKEA","campaign":"셀프 조립 경험 설계","industry":"가구/리테일","year":"지속적","background":"가구를 완제품으로 배송하면 물류비가 크게 오르는 구조적 문제를 이케아는 셀프 조립으로 해결해야 했다.","strategy":"셀프 조립이라는 제약을 오히려 내가 직접 만들었다는 경험으로 재설계하고, 매장 동선 자체도 체험형으로 구성했다.","result":"셀프 조립 제품에 대한 소비자의 애착과 만족도가 완제품보다 높게 나타나는 심리적 효과(이케아 효과)가 학계에서도 검증되며 브랜드 자산이 됐다.","lesson":"고객이 과정의 일부에 참여하게 만들면(예: 컨셉 회의에 직접 참여시키기) 결과물에 대한 만족도와 애착이 커진다."}', '{체험마케팅,심리학}'),
('marketing_case','버드와이저 — Whassup', '{"company":"Budweiser","campaign":"Whassup","industry":"주류","year":"2000","background":"2000년대 초 맥주 브랜드들은 대형 스포츠 이벤트 광고 경쟁이 치열했고, 차별화된 임팩트가 필요했다.","strategy":"복잡한 메시지 없이 친구들끼리 전화로 외치는 짧고 단순한 구호 하나를 반복 노출시켰다.","result":"슈퍼볼 방영 직후 일상 대화·패러디 영상으로 빠르게 확산되며 별도 매체 집행 없이도 브랜드 인지도가 크게 올라갔다.","lesson":"메시지가 복잡할수록 확산은 어렵다 — 한 문장, 한 장면으로 기억에 남는 것이 광고비 대비 효율이 높다."}', '{바이럴,대중문화}'),
('marketing_case','맥도날드 — I''m Lovin'' It', '{"company":"McDonald''s","campaign":"I''m Lovin'' It","industry":"외식/패스트푸드","year":"2003~","background":"국가마다 다른 슬로건을 쓰던 맥도날드는 글로벌 브랜드 자산을 통일할 필요가 있었다.","strategy":"전 세계 모든 매장·광고에 동일한 슬로건과 징글을 적용해 언어가 달라도 같은 브랜드로 인식되게 만들었다.","result":"이후 20년 넘게 유지되는, 역사상 가장 성공적인 글로벌 통합 브랜드 자산 중 하나로 꼽힌다.","lesson":"여러 채널(인스타/블로그/플레이스)을 운영할 때 문구·톤을 통일하는 것만으로도 브랜드 인지도가 축적된다."}', '{브랜딩,글로벌통합}'),
('marketing_case','던킨 — 브랜드명 리뉴얼', '{"company":"Dunkin''","campaign":"Donuts를 뺀 리브랜딩","industry":"외식/카페","year":"2019","background":"소비자들이 도넛 매장으로만 인식해 커피·음료 판매 확대에 한계가 있었다.","strategy":"공식 브랜드명에서 Donuts를 빼고 Dunkin''으로 축약해 온더고(on-the-go) 음료 브랜드로 포지셔닝을 재설정했다.","result":"브랜드명 변경 이후 음료 카테고리 매출 비중이 늘어나는 등 포지셔닝 전환이 실제 매출 구조 변화로 이어졌다.","lesson":"브랜드가 실제로 하는 일이 이름이 주는 인상과 어긋나 있다면, 이름·슬로건을 먼저 정리하는 것이 다른 마케팅보다 우선일 수 있다."}', '{리브랜딩,포지셔닝}'),
('marketing_case','넷플릭스 — 데이터 기반 개인화', '{"company":"Netflix","campaign":"추천 알고리즘을 마케팅 자산으로 활용","industry":"스트리밍","year":"지속적","background":"콘텐츠 양이 방대해질수록 사용자가 원하는 것을 찾지 못해 이탈하는 문제가 커졌다.","strategy":"광고 대신 시청 데이터를 기반으로 사용자마다 다른 썸네일과 추천 목록을 실시간으로 보여주는 개인화 시스템 자체를 마케팅으로 설계했다.","result":"개인화 추천은 신규 콘텐츠 발견율과 리텐션을 높이는 핵심 동력으로 자리잡아, 별도 광고 없이도 재방문을 유도하는 구조를 만들었다.","lesson":"고객 데이터(과거 촬영 스타일, 선호 컨셉)를 쌓아두고 다음 제안에 반영하면, 그 자체가 나를 잘 아는 스튜디오라는 마케팅이 된다."}', '{데이터마케팅,개인화}'),
('marketing_case','구글 — Year in Search', '{"company":"Google","campaign":"Year in Search","industry":"IT/검색","year":"2009~","background":"검색이라는 제품은 이미 일상이 되어 있어 광고로 새롭게 알릴 게 많지 않았다.","strategy":"자사 제품을 홍보하지 않고, 한 해 동안 사람들이 검색한 키워드를 감성적 영상으로 재구성해 순수한 스토리텔링 콘텐츠로 공개했다.","result":"매년 연말 화제가 되는 콘텐츠로 자리잡아, 제품 언급 없이도 검색이라는 제품의 가치를 체감시키는 효과를 냈다.","lesson":"한 해 동안 쌓인 우리만의 데이터(촬영 건수, 인기 컨셉 등)를 연말 회고 콘텐츠로 만들면 고객·잠재고객 모두에게 자연스러운 브랜드 노출이 된다."}', '{스토리텔링,연말캠페인}'),
('marketing_case','벤앤제리스 — 사회적 이슈 연대', '{"company":"Ben & Jerry''s","campaign":"사회정의 이슈 공개 지지","industry":"식품(아이스크림)","year":"지속적","background":"아이스크림처럼 관여도가 낮은 카테고리에서 브랜드 충성도를 만들기 위해서는 제품 이상의 가치가 필요했다.","strategy":"기후변화, 인종평등 등 민감한 사회 이슈에 대해 브랜드가 직접 입장을 밝히고 캠페인을 전개했다.","result":"일부 반발도 있었지만 가치관에 공감하는 소비자층과의 유대는 오히려 강해졌고, 사회적 발언을 하는 브랜드의 대표 사례로 자리잡았다.","lesson":"원장님·대표님이 실제로 믿는 가치가 있다면 이를 콘텐츠에 녹이는 것이 차별화 포인트가 될 수 있다."}', '{사회적마케팅,브랜드가치}'),
('marketing_case','슬랙 — 제품주도성장(PLG)', '{"company":"Slack","campaign":"무료 사용 기반 입소문 확산","industry":"협업툴/SaaS","year":"2013~","background":"초기 슬랙은 마케팅 예산이 크지 않은 스타트업이었다.","strategy":"광고 대신 무료 사용자가 팀원을 직접 초대하는 제품 구조 자체를 성장 엔진으로 설계했다.","result":"별도 영업조직 없이도 사용자 기반이 빠르게 확산됐고, 이후 여러 SaaS 기업이 따라하는 PLG(Product-Led Growth) 모델의 대표 사례가 됐다.","lesson":"만족한 고객이 자연스럽게 다음 고객을 데려오는 구조(추천 리워드 등)를 만들면 광고비 없이도 성장할 수 있다."}', '{PLG,입소문}'),
('marketing_case','곰표 — 곰표 밀맥주 콜라보', '{"company":"대한제분(곰표)","campaign":"곰표 밀맥주","industry":"식품/유통(한국)","year":"2020","background":"70년 넘은 밀가루 브랜드 곰표는 올드한 이미지로 젊은 세대와의 접점이 거의 없었다.","strategy":"브랜드 로고와 캐릭터를 그대로 살려 맥주, 패딩, 화장품 등 전혀 다른 카테고리 제품과 협업했다.","result":"곰표 밀맥주는 출시 직후 편의점에서 품절 사태를 겪을 정도로 화제가 됐고, 오래된 브랜드 자산 재해석이라는 뉴트로 마케팅의 국내 대표 사례가 됐다.","lesson":"오래된 브랜드 자산(로고, 슬로건)도 의외의 협업 방식으로 재해석하면 새로운 화제성을 만들 수 있다."}', '{뉴트로,콜라보}'),
('marketing_case','배달의민족 — B급 감성 카피', '{"company":"배달의민족","campaign":"옥외광고·카피 캠페인","industry":"배달/플랫폼(한국)","year":"2015~","background":"배달앱은 기능적으로 비슷비슷해 감성적 차별화가 필요했다.","strategy":"진지한 광고 문법 대신 힘을 뺀 유머러스한 카피로 옥외광고·SNS를 채우고, 폰트까지 자체 제작해 배포했다.","result":"배달앱 중에서도 가장 친근한 브랜드 이미지를 구축했고, 자체 제작 폰트는 무료 배포를 통해 별도의 브랜드 홍보 효과까지 얻었다.","lesson":"진지한 업종일수록, 지나치지 않은 선에서 톤을 살짝 낮춘 콘텐츠가 오히려 기억에 남을 수 있다."}', '{카피라이팅,브랜드팬덤}'),
('marketing_case','오뚜기 — 신뢰 기반 브랜드 이미지', '{"company":"오뚜기","campaign":"정직경영 이슈의 자발적 확산","industry":"식품(한국)","year":"지속적","background":"식품업계는 크고 작은 불매운동 이슈가 잦아 소비자 신뢰가 취약한 업종이다.","strategy":"별도의 캠페인 없이 상속세 완납, 정규직 채용 비율 등 실제 경영 방식을 유지했고, 이것이 소비자 사이에서 자발적으로 회자됐다.","result":"광고비를 들이지 않고도 소비자가 스스로 만든 신뢰 캠페인이 형성돼 장기적인 브랜드 호감도로 이어졌다.","lesson":"가장 강력한 마케팅은 광고가 아니라 실제 행동이다 — 병원의 진료 방식·직원 대우 자체가 알려지면 그 이상의 광고 효과를 낼 수 있다."}', '{기업신뢰,자발적확산}'),
('marketing_case','마켓컬리 — 새벽배송 카테고리 개척', '{"company":"마켓컬리","campaign":"샛별배송","industry":"이커머스(한국)","year":"2015~","background":"신선식품 배송은 품질 유지가 어려워 아무도 새벽 배송을 상용화하지 못한 상태였다.","strategy":"프리미엄 포지셔닝을 유지하며 전날 밤 주문하면 다음날 새벽 문 앞에 도착하는 물류 시스템을 처음으로 구축했다.","result":"후발주자들이 뒤따라 진입할 만큼 새벽배송이라는 소비 카테고리 자체를 새로 만들어냈다.","lesson":"아무도 하지 않는 서비스(예: 촬영 당일 즉시 초안 전달)를 먼저 상용화하면 카테고리 자체를 선점할 수 있다."}', '{카테고리창출,프리미엄}'),
('marketing_case','무신사 — 커뮤니티 기반 성장', '{"company":"무신사","campaign":"패션 커뮤니티에서 플랫폼으로","industry":"패션/이커머스(한국)","year":"2001~","background":"초기 온라인 패션 시장은 신뢰할 만한 정보가 부족했다.","strategy":"판매보다 먼저 패션 정보를 공유하는 커뮤니티를 운영해 신뢰를 쌓은 뒤, 자연스럽게 커머스 플랫폼으로 확장했다.","result":"판매 채널로 전환한 이후에도 초기 커뮤니티에서 쌓은 신뢰 덕분에 빠르게 충성 고객층을 확보할 수 있었다.","lesson":"판매를 서두르기보다 먼저 유용한 정보·콘텐츠로 신뢰를 쌓으면, 이후 상품·서비스 전환이 훨씬 수월해진다."}', '{커뮤니티,플랫폼확장}'),
('marketing_case','오레오 — Dunk in the Dark', '{"company":"Oreo","campaign":"Dunk in the Dark","industry":"식품(과자)","year":"2013","background":"2013년 슈퍼볼 중계 도중 경기장에 정전이 발생하는 예상치 못한 상황이 벌어졌다.","strategy":"정전이 발생한 직후 몇 분 안에 정전 중에도 오레오는 어둠 속에서 찍어먹을 수 있다는 트윗을 즉각 게시했다.","result":"별도의 매체비 없이 올린 트윗 하나가 그날 가장 많이 회자된 광고 콘텐츠로 언급되며 실시간 대응 마케팅(newsjacking)의 대표 사례가 됐다.","lesson":"큰 예산보다 상황을 빠르게 포착해 재치있게 반응하는 순발력이 임팩트를 만들 수 있다 — 지역 이슈나 시즌 트렌드에 빠르게 반응하는 콘텐츠를 준비해두면 좋다."}', '{실시간마케팅,SNS}'),
('marketing_case','버거킹 — Whopper Detour', '{"company":"Burger King","campaign":"Whopper Detour","industry":"외식/패스트푸드","year":"2018","background":"버거킹은 앱 다운로드를 늘려야 했지만 이미 시장에 배달·할인 앱이 넘쳐나는 상황이었다.","strategy":"자사 앱으로 경쟁사인 맥도날드 매장 근처 600피트 이내에서 주문해야만 와퍼를 1센트에 살 수 있게 설계했다.","result":"프로모션 기간 동안 버거킹 앱이 앱스토어 다운로드 순위 상위권에 오르는 등 위치 기반 마케팅의 파급력을 입증했다.","lesson":"경쟁사와 비교하기보다, 경쟁사의 위치나 맥락 자체를 창의적으로 활용하면 적은 비용으로 큰 화제를 만들 수 있다."}', '{위치기반마케팅,경쟁사활용}'),
('marketing_case','이니스프리 — 자연주의 스토리텔링', '{"company":"이니스프리","campaign":"제주 원산지 브랜딩","industry":"뷰티(한국)","year":"지속적","background":"국내 화장품 시장은 브랜드가 많아 원료·산지 스토리로 차별화하는 경쟁이 치열했다.","strategy":"제주라는 단일 컨셉을 원료 산지 스토리부터 매장 인테리어, 패키지 디자인까지 모든 접점에서 반복 노출했다.","result":"특정 지역 이미지를 브랜드 정체성으로 완전히 각인시킨 대표 국내 뷰티 브랜드 사례로 꼽힌다.","lesson":"여러 메시지를 산발적으로 전달하기보다, 하나의 컨셉을 모든 채널(인스타·블로그·매장)에서 반복하면 훨씬 강하게 각인된다."}', '{브랜드일관성,원산지스토리}');
insert into public.library_items (category, title, content, tags) values
('consulting_framework','맥킨지 7S 모델', '{"firm":"McKinsey","description":"조직을 Strategy, Structure, Systems, Shared Values, Skills, Style, Staff 7가지 요소로 나눠 정합성을 진단하는 조직 분석 프레임워크.","steps":["7가지 요소(전략/구조/시스템/공유가치/역량/스타일/인력)의 현재 상태를 각각 적는다","요소 간 서로 충돌하는 지점을 찾는다(예: 새 전략인데 조직 구조가 그대로인 경우)","가장 큰 불일치부터 우선순위를 정해 조정 계획을 세운다"],"example":"촬영 스튜디오가 병원 브랜드 컨설팅까지 사업을 확장하기로 했다면(전략 변경), 촬영 위주로 짜인 조직 구조와 인력 역량도 함께 바뀌어야 하는지 7S로 점검할 수 있다.","use_case":"조직개편, 합병 후 통합(PMI) 시 조직 정합성 점검"}', '{조직,전략}'),
('consulting_framework','BCG 매트릭스', '{"firm":"Boston Consulting Group","description":"사업(제품)을 시장성장률과 상대적 시장점유율 두 축으로 Star/Cash Cow/Question Mark/Dog 4분면에 배치해 포트폴리오를 분석하는 기법.","steps":["보유한 모든 사업/서비스 라인을 나열한다","각각의 시장성장률과 시장점유율(경쟁사 대비)을 평가한다","4분면에 배치하고 Star는 투자, Cash Cow는 수익원 유지, Question Mark는 선별 투자, Dog는 철수를 검토한다"],"example":"병원 촬영(주력, 안정적 수익), 홈페이지 제작(신규, 성장 중), 인스타 디자인(정체) 세 서비스를 매트릭스에 배치해 어디에 더 투자할지 판단할 수 있다.","use_case":"사업 포트폴리오 우선순위 결정, 투자/철수 판단"}', '{포트폴리오,전략}'),
('consulting_framework','포터의 5가지 경쟁요인', '{"firm":"Michael Porter (Harvard)","description":"기존 경쟁자, 신규 진입자, 대체재, 구매자 교섭력, 공급자 교섭력 5가지로 산업의 매력도와 경쟁 구조를 분석하는 프레임워크.","steps":["업종 내 기존 경쟁자의 강도를 평가한다","새로운 경쟁자가 얼마나 쉽게 진입할 수 있는지 본다","대체재(다른 방식으로 같은 니즈를 해결하는 것)가 무엇인지 찾는다","고객과 공급자 각각의 협상력을 평가한다"],"example":"병원 촬영 시장에 프리랜서 작가, AI 이미지 생성 도구(대체재), 대형 에이전시(신규 진입)가 어떤 압박을 주는지 정리하면 방어 전략을 세울 수 있다.","use_case":"신규 시장 진출 타당성 검토, 산업 구조 분석"}', '{산업분석,경쟁전략}'),
('consulting_framework','SWOT 분석', '{"firm":"범용(경영학 기본)","description":"내부 요인(강점/약점)과 외부 요인(기회/위협)을 교차 분석해 전략 방향을 도출하는 가장 기본적인 전략 수립 도구.","steps":["강점(내부, 잘하는 것)과 약점(내부, 부족한 것)을 각각 적는다","기회(외부, 유리한 흐름)와 위협(외부, 불리한 흐름)을 적는다","강점X기회는 공격 전략, 약점X위협은 방어/보완 전략으로 교차 연결한다"],"example":"강점(빠른 리터칭)X기회(SNS 콘텐츠 수요 증가)를 교차하면 숏폼 콘텐츠 익일 납품 같은 신규 서비스 아이디어가 나올 수 있다.","use_case":"사업계획서, 신규 프로젝트 착수 전 상황 진단"}', '{전략,기획}'),
('consulting_framework','블루오션 전략', '{"firm":"INSEAD (김위찬·르네 마보안)","description":"경쟁이 치열한 기존 시장(레드오션)을 벗어나, 가치와 비용을 동시에 낮추거나 새로운 가치를 창출해 경쟁이 없는 새 시장을 만드는 전략론. ERRC(제거-감소-증가-창조) 프레임 사용.","steps":["업계가 당연하게 여기는 요소 중 제거할 것을 정한다","업계 표준보다 줄여도 되는 요소를 찾는다","표준보다 늘려야 할 요소를 찾는다","업계에 없던 새로운 요소를 창조한다"],"example":"기존 촬영이 스튜디오 방문을 당연시했다면, 병원 내 방문 촬영을 늘리고(증가) 온라인 셀렉 갤러리를 새로 만드는(창조) 식으로 ERRC를 적용할 수 있다.","use_case":"신사업 기획, 차별화 전략 수립"}', '{차별화,신사업}'),
('consulting_framework','MECE 원칙', '{"firm":"McKinsey","description":"Mutually Exclusive, Collectively Exhaustive(상호 배타적이며 전체를 포괄하는) 원칙. 문제를 중복 없이, 빠짐없이 구조화하는 컨설턴트의 기본 사고법.","steps":["큰 질문을 하위 항목으로 쪼갠다","항목끼리 겹치는 부분이 있는지 확인하고 제거한다(상호 배타적)","빠진 항목이 없는지 전체를 다시 점검한다(전체 포괄)"],"example":"매출이 왜 줄었나를 신규 고객 감소와 기존 고객 재구매 감소로 나누면(겹치지 않고 전체를 포괄) 원인을 더 명확히 찾을 수 있다.","use_case":"문제 정의, 보고서/제안서 구조화"}', '{문제해결,사고법}'),
('consulting_framework','균형성과표(BSC)', '{"firm":"Robert Kaplan & David Norton (Harvard)","description":"재무, 고객, 내부프로세스, 학습과성장 4가지 관점에서 균형 있게 성과를 관리하는 프레임워크. 재무지표에만 치우친 평가의 한계를 보완.","steps":["재무 관점(매출, 이익) 지표를 정한다","고객 관점(만족도, 재구매율) 지표를 정한다","내부프로세스 관점(납품 리드타임, 오류율) 지표를 정한다","학습과성장 관점(직원 역량, 신규 도구 도입) 지표를 정한다"],"example":"매출만 보지 않고 고객 재구매율, 납품 리드타임, 직원 신규 스킬 습득 지표를 함께 관리하면 장기적 성장 기반을 놓치지 않을 수 있다.","use_case":"조직 성과 관리, KPI 설계"}', '{성과관리,KPI}'),
('consulting_framework','디자인 씽킹', '{"firm":"IDEO / Stanford d.school","description":"공감(Empathize)-정의(Define)-아이디어(Ideate)-프로토타입(Prototype)-테스트(Test) 5단계로 사용자 중심 문제해결을 하는 방법론.","steps":["고객을 직접 관찰·인터뷰해 진짜 니즈를 공감한다","발견한 니즈를 명확한 문제로 정의한다","제약 없이 다양한 해결 아이디어를 낸다","가장 유력한 아이디어를 빠르게 시제품으로 만든다","실제 고객에게 테스트하고 피드백으로 개선한다"],"example":"원장님을 직접 인터뷰해 사진보다 후기 콘텐츠가 더 급하다는 진짜 니즈를 발견했다면, 그에 맞는 리뷰 콘텐츠 서비스를 빠르게 시범 제공하고 반응을 볼 수 있다.","use_case":"신제품/서비스 기획, 고객경험 개선"}', '{혁신,고객경험}'),
('consulting_framework','앤소프 매트릭스', '{"firm":"Igor Ansoff","description":"기존/신규 시장과 기존/신규 제품 두 축으로 시장침투·시장개발·제품개발·다각화 4가지 성장 전략을 구분하는 프레임워크.","steps":["기존 고객에게 기존 서비스를 더 팔 방법을 찾는다(시장침투)","기존 서비스를 새로운 고객군에 제안한다(시장개발)","기존 고객에게 새로운 서비스를 만들어 제안한다(제품개발)","완전히 새로운 고객X새로운 서비스 조합을 검토한다(다각화)"],"example":"기존 병원 고객에게 리뷰 콘텐츠 서비스를 추가 제안하는 것은 제품개발, 병원이 아닌 카페·미용실로 촬영 서비스를 넓히는 것은 시장개발에 해당한다.","use_case":"신규 성장 전략 수립, 사업 확장 방향 결정"}', '{성장전략,포트폴리오}'),
('consulting_framework','PESTEL 분석', '{"firm":"범용(거시환경 분석 기본)","description":"정치(Political)·경제(Economic)·사회(Social)·기술(Technological)·환경(Environmental)·법률(Legal) 6가지 거시환경 요인을 분석하는 프레임워크.","steps":["6가지 항목 각각에 업종에 영향을 주는 변화를 적는다","그 변화가 기회인지 위협인지 표시한다","가장 임박한 위협부터 대응 계획을 세운다"],"example":"의료광고법 개정(법률), AI 이미지 생성 확산(기술) 같은 변화를 미리 정리해두면 서비스 방향을 선제적으로 조정할 수 있다.","use_case":"신규 시장 진출, 중장기 사업계획 수립 시 외부환경 점검"}', '{거시환경,전략}'),
('consulting_framework','가치사슬 분석', '{"firm":"Michael Porter (Harvard)","description":"기업 활동을 본원적 활동(구매·생산·물류·마케팅·서비스)과 지원 활동(인프라·인사·기술·조달)으로 나눠 어느 단계에서 가치와 원가가 발생하는지 분석하는 프레임워크.","steps":["촬영 의뢰부터 최종 납품까지 전체 프로세스를 단계별로 나열한다","각 단계에서 드는 시간/비용과 고객이 느끼는 가치를 함께 적는다","비용은 큰데 고객 가치가 낮은 단계를 찾아 개선한다"],"example":"리터칭 단계에 시간이 가장 많이 들지만 고객은 빠른 전달을 더 가치있게 여긴다면, 리터칭 자동화 도구 도입을 우선 검토할 수 있다.","use_case":"원가 절감 포인트 발굴, 경쟁우위 요소 파악"}', '{가치사슬,경쟁우위}'),
('consulting_framework','린 스타트업', '{"firm":"Eric Ries","description":"Build-Measure-Learn(구축-측정-학습) 루프를 빠르게 반복해 최소기능제품(MVP)으로 가설을 검증하고, 필요하면 신속히 피벗하는 방법론.","steps":["가장 작은 형태로 아이디어를 실제로 만들어본다(MVP)","소수의 실제 고객에게 제공하고 반응을 측정한다","측정 결과로 가설이 맞았는지 배우고, 다음 버전을 결정한다"],"example":"새 서비스(예: AI 이미지 생성)를 전체 시스템으로 만들기 전에, 몇몇 고객에게 수동으로 먼저 제공해보고 반응이 좋을 때만 본격 개발하는 방식이다.","use_case":"신사업/신제품 초기 검증, 불확실성이 큰 시장에서의 빠른 실험"}', '{린스타트업,MVP}'),
('consulting_framework','Jobs to be Done', '{"firm":"Clayton Christensen (Harvard)","description":"고객이 제품·서비스를 고용하는 근본 이유, 즉 해결하고자 하는 과업(Job) 관점에서 혁신 기회를 찾는 이론.","steps":["고객이 서비스를 쓰는 표면적 이유가 아니라 진짜 해결하려는 상황을 묻는다","그 상황(Job)을 대체할 수 있는 다른 방법들과 비교한다","그 Job을 더 잘 해결하는 방향으로 서비스를 재설계한다"],"example":"병원이 촬영을 고용하는 진짜 이유가 예쁜 사진이 아니라 신규 환자에게 신뢰를 주는 것이라면, 사진 퀄리티보다 후기·신뢰 콘텐츠 강화가 더 맞는 해결책일 수 있다.","use_case":"제품 혁신 아이디어 발굴, 진짜 고객 니즈 재정의"}', '{고객니즈,혁신}'),
('consulting_framework','캐즘 이론', '{"firm":"Geoffrey Moore","description":"혁신 제품이 초기 얼리어답터를 넘어 실용적인 주류 시장으로 확산될 때 겪는 단절(캐즘)을 어떻게 건너는지 설명하는 하이테크 마케팅 이론.","steps":["얼리어답터(새로운 것을 먼저 시도하는 고객)에게 먼저 검증받는다","얼리어답터의 성공 사례를 구체적 레퍼런스로 만든다","그 레퍼런스로 보수적인 주류 고객을 설득한다"],"example":"AI 이미지 생성 같은 신규 서비스는 새로운 것을 좋아하는 병원 한두 곳에서 먼저 성공 사례를 만든 뒤, 그 사례로 보수적인 병원들을 설득하는 순서가 유효하다.","use_case":"신기술/신제품의 대중화 전략 수립"}', '{제품확산,하이테크마케팅}'),
('consulting_framework','OKR', '{"firm":"Andy Grove(Intel) / John Doerr","description":"Objectives(정성적 목표)와 Key Results(정량적 핵심결과)를 연결해 조직 전체의 목표를 정렬시키는 목표관리 기법.","steps":["분기 단위로 방향성을 담은 정성적 목표(Objective)를 정한다","그 목표 달성 여부를 판단할 수 있는 정량적 핵심결과(Key Result) 2~4개를 정한다","매주/매월 진행률을 점검하고 다음 분기에 반영한다"],"example":"Objective 신규 병원 확보 가속화, Key Results 이번 분기 신규 계약 5건 / 재계약률 90% 유지처럼 팀 전체가 같은 숫자를 보고 움직이게 만들 수 있다.","use_case":"조직/팀 목표 설정, 실리콘밸리식 성과관리 도입"}', '{목표관리,OKR}'),
('consulting_framework','코터의 8단계 변화관리 모델', '{"firm":"John Kotter (Harvard)","description":"위기감 조성, 변화추진팀 구성, 비전 수립부터 변화의 조직문화 정착까지 8단계로 조직 변화를 성공적으로 이끄는 프레임워크.","steps":["왜 지금 변화가 필요한지 위기감을 조성한다","변화를 이끌 소규모 핵심팀을 구성한다","명확한 비전과 실행 전략을 세운다","단기 성과를 만들어 변화가 통한다는 것을 보여준 뒤 조직문화로 정착시킨다"],"example":"촬영 방식을 새 워크플로우로 바꿀 때, 왜 바꿔야 하는지 팀에 먼저 설명하고 한두 프로젝트에서 작은 성공을 먼저 보여주면 전체 도입 저항이 줄어든다.","use_case":"조직개편, 대규모 변화관리 프로젝트"}', '{변화관리,조직}'),
('consulting_framework','RACI 매트릭스', '{"firm":"범용(프로젝트관리 기본)","description":"업무별로 담당자를 Responsible(실무 담당)·Accountable(최종 책임)·Consulted(자문)·Informed(공유 대상)로 구분해 역할과 책임을 명확히 하는 도구.","steps":["프로젝트의 주요 업무를 목록으로 나열한다","각 업무마다 실무 담당자(R)와 최종 책임자(A)를 한 명씩 지정한다","의견을 물어야 할 사람(C)과 결과만 공유하면 되는 사람(I)을 구분한다"],"example":"최종 파일 전달 업무에서 리터칭 담당자가 R, 대표님이 A, 촬영 담당자가 C, 고객 담당자가 I로 지정되면 누가 무엇을 결정하는지 헷갈리지 않는다.","use_case":"프로젝트 역할분담, 협업 시 책임소재 명확화"}', '{프로젝트관리,역할분담}'),
('consulting_framework','카노 모델', '{"firm":"Noriaki Kano","description":"제품 속성을 기본 품질(당연히 있어야 함)·성과 품질(있을수록 만족도 비례)·매력 품질(없어도 무관하지만 있으면 감동) 3가지로 분류해 개발 우선순위를 정하는 기법.","steps":["고객이 당연하게 기대하는 기본 요소를 파악한다(없으면 불만)","많을수록 만족도가 비례하는 성과 요소를 파악한다","없어도 무방하지만 있으면 감동을 주는 매력 요소를 찾는다","기본 요소부터 확실히 채운 뒤 매력 요소에 투자한다"],"example":"납기 준수는 기본 품질, 리터칭 퀄리티는 성과 품질, 예상 못한 감사 손편지 동봉은 매력 품질에 해당해 우선순위를 나눠 투자할 수 있다.","use_case":"제품 기능 우선순위 결정, 고객만족 요소 분석"}', '{제품기획,고객만족}'),
('consulting_framework','GE-맥킨지 매트릭스', '{"firm":"GE & McKinsey","description":"시장매력도와 사업경쟁력 두 축으로 사업을 9분면에 배치해 투자·유지·철수를 판단하는 BCG 매트릭스의 확장판 포트폴리오 분석 기법.","steps":["각 사업의 시장매력도(성장성, 수익성 등 복수 지표)를 종합 평가한다","각 사업에서 우리의 경쟁력(점유율, 브랜드력 등)을 종합 평가한다","9분면에 배치해 높은 매력도X높은 경쟁력 사업에 우선 투자한다"],"example":"BCG 매트릭스보다 더 다양한 지표(브랜드력, 기술력 등)를 함께 고려하고 싶을 때, 단일 축의 한계를 보완해 판단할 수 있다.","use_case":"다각화된 사업 포트폴리오의 투자 우선순위 결정"}', '{포트폴리오,투자판단}'),
('consulting_framework','스크럼', '{"firm":"Jeff Sutherland & Ken Schwaber","description":"2~4주 단위의 짧은 스프린트로 개발·점검을 반복하며 우선순위가 높은 일부터 처리하는 대표적 애자일 프로젝트 관리 방법론.","steps":["해야 할 일을 우선순위 목록(백로그)으로 정리한다","2주 단위로 그중 일부만 떼어 이번 스프린트 목표로 정한다","매일 짧게 진행상황을 공유한다","스프린트가 끝나면 결과를 점검하고 다음 스프린트 목표를 다시 정한다"],"example":"큰 신기능 개발을 한 번에 끝내려 하지 않고, 2주 단위로 작은 기능부터 완성하며 계속 점검하는 방식이 스크럼이다.","use_case":"소프트웨어 개발, 빠른 반복이 필요한 프로젝트 운영"}', '{애자일,프로젝트관리}');
